the reduced LGP vertex; it is not asserted to be the paper's \`F_LGP\` (R3). -/`);
const listMark = `5. The exact placement of S1895's \`paper_strip_identification\` slot: it is`;
const listAdd = `5. The anchor is the lower-left (LGP) vertex of the package's actual
   Kummer-evaluation square \`(paperFullLogKummerUQ D).evaluationSquare\`.
6. The exact placement of S1895's \`paper_strip_identification\` slot: it is`;
if (!c.includes(listMark)) throw new Error("list mark not found");
c = c.replace(listMark, listAdd);
await tools.write({ file_path: "D:\\lean\\tmp\\sheaf\\xif\\paper\\S1960QPilotAnchorActual.lean", content: c });
console.log("edited, bytes", c.length);
const r = await tools.pwsh({ description: "Rebuild S1960 olean after doc edits", command: "lake env lean -j1 -R \"D:\\lean\" -o .lake/build/lib/lean/tmp/sheaf/xif/paper/S1960QPilotAnchorActual.olean tmp/sheaf/xif/paper/S1960QPilotAnchorActual.lean 2>&1 | Tee-Object -FilePath tmp/sheaf/xif/paper/S1960.olean.log | Out-String; \"EXIT=$LASTEXITCODE\"", workdir: "D:\\lean", timeoutMs: 900000 });
console.log(r.kind === "foreground" ? r.stdout.text + "\nSTDERR:\n" + r.stderr.text : JSON.stringify(r));
", "description": "Fix docs and rebuild olean"}

